import java.util.concurrent.ConcurrentSkipListMap;
import java.util.Map;

public class DistributedLeaderboardService {
    // Thread-safe ordered map powered by a skip list implementation
    private final ConcurrentSkipListMap<Integer, String> leaderboard = new ConcurrentSkipListMap<>();

    public void recordScore(int score, String playerId) {
        // O(log n) expected time complexity under high concurrency
        leaderboard.put(score, playerId);
    }

    public void printTopPlayers() {
        System.out.println("--- Top Players (Descending) ---");
        // Descending map view leverages skip list's bidirectional pointers
        leaderboard.descendingMap().entrySet().stream()
            .limit(10)
            .forEach(entry -> System.out.println(entry.getValue() + ": " + entry.getKey()));
    }
}
